"""Upgrade Form Two French Term Three, rows 70–81, without changing other terms."""
import json
import sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
import lessonlib as L
import banks_fr as B
L.use_class('form-2','Form 2')
OUT=L.ROOT/'french'
SRC=['qualite-t3']
PATH=[]
def F(term,meaning,case,error,why): return dict(term=term,meaning=meaning,case=case,error=error,why=why)
def item(q,r,w,y):
    assert len(w)==3
    return dict(q=q,r=r,w=[a for a,b in w],e=[b for a,b in w],y=y)
def qa(n,key,level,bank,**kw): return B.QA(f'fr2-{n}-{key}',level,'{X.q}',bank,SRC,**kw)
def choose(n,rows,key='appliquer',level=2):
    return qa(n,key,level,[item(q,r,list(zip(w,e)),y) for q,r,w,e,y in rows])
def unit(n,title,goal,back,onward,note,model,method,facts,applied,prereq=(),paper=None,extra=None,figure=None,example=None):
    assert 4<=len(facts)<=6
    defs=[]; cases=[]
    for i,f in enumerate(facts):
        others=[x for j,x in enumerate(facts) if j!=i][:3]
        defs.append(item('Quel terme désigne '+f['meaning']+' ?',f['term'],[(x['term'],'Cela désigne '+x['meaning']+', plutôt que la notion demandée.') for x in others],f['why']))
        cases.append(item(f['case']+'\nQuelle notion convient ?',f['term'],[(x['term'],'Cela concerne '+x['meaning']+'. Compare cette définition avec le cas présenté.') for x in others],f['why']))
    q0=qa(n,'notions',1,defs); q1=qa(n,'cas',1,cases)
    q3=extra or B.MT(f'fr2-{n}-relier',2,'Relie chaque notion à son exemple.',[(f['term'],f['case']) for f in facts],SRC,pick=3)
    q4=B.SP(f'fr2-{n}-corriger',3,'Repère la formulation ou l’affirmation incorrecte.',[f['term']+' : '+f['meaning']+'.' for f in facts],[(f['error'],f['why']) for f in facts],SRC)
    for st,f in zip(q4['pool']['right'],facts): st['explain']='Cette distinction est correcte : '+f['why']+' Cherche plutôt une phrase qui contredit le sens ou la règle.'
    sections=[('Ton objectif et les liens','À la fin, tu pourras '+goal+'. Acquis mobilisés : '+back+'. Pour la suite : '+onward+'.'),('Comprendre la règle ou le sens',note),('Lire le modèle original',model),('Appliquer et vérifier',method)]
    if figure: sections[2]=(*sections[2],figure)
    L.lesson('french','french',n,(f'fr2-{n}',title),prereq,note,
      example or L.worked({},facts[0]['case']+' Explique le choix.',[facts[0]['meaning']+'.',facts[0]['why']],facts[0]['term']),
      [L.card(f'fr2-{n}-c1','Distingue les notions avant de choisir.',[f['term']+' : '+f['meaning']+'.' for f in facts],q0['id']),
       L.card(f'fr2-{n}-c2','Lis le contexte avant de nommer la notion.',[f['case'] for f in facts],q1['id']),
       L.card(f'fr2-{n}-c3','Corrige sans changer le sens voulu.',[f['error']+' Correction : '+f['why'] for f in facts],q4['id'])],
      [q0,q1,applied,q3,q4],paper=paper,lang='fr',learn=L.learn(sections,key_words=[(f['term'],f['meaning']) for f in facts],mistake=(facts[0]['error'],facts[0]['meaning']+'.',facts[0]['why'])))
    PATH.append((n,title,goal,back,onward))

unit(70,'Préparer une communication téléphonique','choisir une réplique adaptée et transmettre un message utile dans un appel fictif',
 'les salutations, les questions et les échanges de classe','la lecture de messages et le vocabulaire numérique',
 'Au début d’un appel, on salue, on se présente et on demande poliment son interlocuteur. On annonce ensuite l’objet de l’appel. Si la personne est absente, un message précise qui appelle, pour qui et pourquoi ; une suite prévue peut être ajoutée. Répéter une information utile permet de vérifier la compréhension. Une prise de congé termine l’échange. L’activité prépare un dialogue écrit : elle ne passe aucun appel et n’entend pas ta voix.',
 'Dialogue original, club fictif de Buea. Bih : « Bonjour, je suis Bih, du club de lecture. Puis-je parler à Mme Nji ? » Ayuk : « Elle est absente. Veux-tu laisser un message ? » Bih : « Merci. Dis-lui que je rappellerai demain au sujet du livre du club. » Ayuk reprend le message. Bih remercie et prend congé. Aucun numéro réel n’est demandé.',
 'Repère le moment de l’échange avant de répondre. Vérifie nom, destinataire et objet du message. Joue ensuite le dialogue avec un partenaire si possible, sans téléphoner à une personne réelle pour cet exercice.',[
 F('présentation','le moment où l’appelant indique qui il est','Bonjour, je suis Bih présente l’appelante.','Un appel poli doit toujours cacher son objet et son appelant.','Une présentation rend l’échange compréhensible.'),
 F('objet de l’appel','la raison pour laquelle la personne appelle','Au sujet du livre précise le motif.','L’objet de l’appel est nécessairement un appareil matériel.','Objet signifie ici raison ou sujet de l’appel.'),
 F('message transmis','les informations utiles données à un intermédiaire','Bih rappellera demain au sujet du livre est un message.','Un message sans destinataire ni motif suffit toujours.','Le message doit pouvoir être transmis à la bonne personne.'),
 F('prise de congé','la clôture polie de l’échange','Merci, au revoir termine le dialogue.','Prendre congé signifie commencer par une accusation.','Il s’agit de terminer l’échange avec politesse.')],
 choose(70,[('Tu appelles et l’interlocuteur décroche. Quelle réplique ouvre clairement l’échange ?','Bonjour, je suis Bih, du club de lecture.',['Tu sais déjà tout sur moi.','Au revoir, nous n’avons pas encore parlé.','Tu dois deviner ma demande.'],['L’identité n’est pas nécessairement connue.','Cette clôture ne présente pas l’appel.','La demande doit être formulée.'],'Une ouverture identifie l’appelant.'),('Mme Nji est absente. Quel message est utile ?','Bih rappellera demain au sujet du livre du club.',['Quelqu’un voulait quelque chose, sans autre détail.','Chaque élève doit publier son numéro privé.','Le livre prouve que tout est déjà réglé.'],['Le destinataire ne saurait pas qui ni pourquoi.','Aucune donnée privée n’est requise.','Cette conclusion n’est pas dans l’appel.'],'Nom, objet et suite rendent le message utilisable.'),('Tu n’es pas certain d’avoir compris le motif. Que peux-tu dire ?','Peux-tu répéter l’objet de l’appel, s’il te plaît ?',['Je vais inventer ton message.','Je publierai le dialogue à toute la classe.','Tu as tort parce que tu as appelé.'],['Une invention change le message.','Le dialogue ne donne pas cette autorisation.','L’accusation ne vérifie rien.'],'Demande une clarification.'),('L’échange est terminé. Quelle clôture convient ?','Merci pour le message, au revoir.',['Quel est ton diagnostic médical ?','Je vais changer ton nom dans le message.','Pourquoi devinerais-je tes coordonnées ?'],['La demande est sans rapport.','Le nom doit rester fidèle.','La formule ne clôt pas clairement l’échange.'],'La prise de congé respecte le contexte.')] ))

unit(71,'Lire : préparer un exposé avec Internet','répondre sur les actions d’un passage et distinguer recherche information et vérification',
 'les messages et les questions','la recherche sur Internet et l’écriture d’un paragraphe',
 'Pour comprendre un passage, relève les actions et leur ordre. Une raison explique pourquoi un personnage agit ; un projet indique ce qu’il compte faire. Lire une page ne prouve pas que toutes ses informations sont exactes. Le nom de l’auteur ou de l’organisme, la date et la comparaison de références peuvent aider à vérifier une information. Les questions portent sur le passage original ci-dessous : tu n’as pas besoin d’ouvrir Internet ni de créer un compte.',
 'Passage original : Bih prépare un exposé sur les marchés dans un club imaginaire de Bamenda. Elle note une question précise avant de chercher. Avec l’enseignante, elle compare une page dont l’organisme et la date sont indiqués à un message anonyme. Elle choisit de vérifier une affirmation et conserve le nom de la source pour la citer. Ayuk l’aide à organiser ses notes. Le passage ne donne pas encore le résultat final de l’exposé.',
 'Relis la phrase utile avant de choisir. Distingue ce que le personnage fait de ce que tu imagines. Pour expliquer un choix, cite un indice du passage plutôt que d’inventer le succès de l’exposé.',[
 F('question de recherche','ce qui guide la recherche d’information','Bih note une question avant de chercher.','Chercher exige de ne jamais savoir ce que l’on cherche.','Une question précise oriente les choix.'),
 F('source identifiable','une origine que l’on peut nommer','Une page indique un organisme et une date.','Le premier résultat est toujours une preuve suffisante.','L’ordre d’affichage ne garantit pas la fiabilité.'),
 F('vérification','l’examen d’une affirmation avant de la reprendre','Bih compare des références avec l’enseignante.','Comparer signifie recopier toute phrase sans l’examiner.','La comparaison doit aider à contrôler le contenu.'),
 F('limite du passage','une information que ce texte ne donne pas','Le bilan final de l’exposé n’est pas fourni.','Le projet prouve déjà la meilleure note de toute la classe.','Le résultat n’est pas raconté.')],
 choose(71,[('Que fait Bih avant de chercher ?','Elle note une question précise.',['Elle publie un numéro privé.','Elle annonce un résultat déjà noté.','Elle invente la date de la page.'],['Le passage ne demande aucun numéro.','Le résultat final n’est pas donné.','La date est un indice à relever, pas à inventer.'],'L’ordre des actions est explicite.'),('Quels indices la page fournit-elle ?','Le nom de l’organisme et la date.',['Le dossier privé de Bih.','Une garantie que toute phrase est vraie.','La note finale de l’exposé.'],['Aucun dossier n’est fourni.','Les indices aident sans tout garantir.','La note reste inconnue.'],'Relève les informations présentes.'),('Pourquoi garder le nom de la source ?','Pour pouvoir la citer.',['Pour prétendre avoir inventé le texte.','Pour supprimer toute vérification.','Pour garantir un résultat scolaire.'],['Citer reconnaît l’origine.','La vérification reste nécessaire.','L’origine ne garantit pas la note.'],'Le motif est annoncé.'),('Quelle conclusion dépasse le passage ?','L’exposé a déjà obtenu un résultat final.',['Ayuk aide à organiser les notes.','Bih compare des références.','L’enseignante accompagne la recherche.'],['Cette aide est écrite.','La comparaison est racontée.','L’accompagnement est donné.'],'Le résultat final n’est pas fourni.')]),[70])

agreement=B.mcq('fr2-72-accorder',2,'Complète au présent : « {X.s} ___ ». Verbe : {v}.','{fr2Present(v,X.p)}',
 [('{fr2Present(v,X.p==2 ? 6 : 2)}','nombre'),('{fr2Present(v,4)}','nous'),('{fr2Present(v,5)}','vous')],['Le sujet est {X.s}.','Sa valeur grammaticale commande {answer}.'],vars={'X':{'pick':[{'s':'Quelqu’un','p':2},{'s':'Chacun','p':2},{'s':'Plusieurs','p':6},{'s':'Certains','p':6}]},'v':{'pick':['parler','lire','écrire','travailler']}},misc=[('nombre','Cette forme change le nombre du pronom sujet.'),('nous','Le sujet donné n’est pas nous.'),('vous','Le sujet donné n’est pas vous.')],sources=SRC)
unit(72,'Reconnaître les pronoms indéfinis','choisir un pronom imprécis et accorder le verbe avec son nombre grammatical',
 'les personnes et les sujets des messages','les emplois négatifs et la reprise des idées',
 'Un pronom indéfini désigne une personne, une chose ou une quantité sans l’identifier exactement. Quelqu’un présente une personne non précisée. Chacun considère chaque membre séparément et commande un verbe singulier. Plusieurs et certains, employés seuls comme sujets, commandent un pluriel. Compare plusieurs lisent et plusieurs élèves lisent : dans le second groupe, plusieurs détermine le nom élèves. On ne reconnaît donc pas un pronom en regardant seulement son orthographe.',
 'Modèles originaux : Quelqu’un {fr2Present("parler",2)} au téléphone. Chacun {fr2Present("lire",2)} son message. Plusieurs {fr2Present("écrire",6)} une question. Dans plusieurs élèves travaillent, élèves est exprimé après le déterminant. Dans plusieurs travaillent, le mot plusieurs est employé comme pronom.',
 'Vérifie si le mot accompagne un nom ou s’emploie sans ce nom. Repère ensuite le sujet et son nombre. Ne mets pas le pluriel après chacun seulement parce que le groupe contient différentes personnes.',[
 F('quelqu’un','une personne dont l’identité n’est pas précisée','Quelqu’un parle sans nommer la personne.','Quelqu’un donne forcément le nom complet de l’appelant.','L’identité reste imprécise.'),
 F('chacun','chaque membre considéré séparément','Chacun lit son message au singulier.','Chacun impose toujours lisent.','Le sujet chacun est grammaticalement singulier.'),
 F('plusieurs pronom','une quantité plurielle sans nom exprimé après le mot','Plusieurs écrivent emploie plusieurs seul comme sujet.','Plusieurs écrit est l’accord attendu dans ce modèle.','Le pronom sujet est pluriel.'),
 F('déterminant indéfini','un mot accompagnant un nom comme plusieurs élèves','Dans plusieurs élèves, le nom est exprimé.','Plusieurs est toujours pronom dans tous ses emplois.','La fonction dépend de la construction.')],agreement,[70,71],example=L.worked({},'Complète : Chacun ___ son message, avec lire au présent.',['Chacun considère les membres séparément.','Le sujet est singulier ; lire prend la forme {fr2Present("lire",2)}.'],'Chacun {fr2Present("lire",2)} son message.'))

def vocabulary(n,title,goal,back,onward,note,model,method,facts,rows,prereq):
    unit(n,title,goal,back,onward,note,model,method,facts,choose(n,rows,key='contexte'),prereq)

vocabulary(73,'Naviguer, chercher et télécharger','choisir le verbe correspondant à une action numérique décrite',
 'le passage sur la recherche','le lexique des TIC et la description d’une démarche',
 'Naviguer ou surfer consiste à passer entre des pages ou ressources en ligne. Chercher consiste à formuler une demande d’information ; un moteur de recherche propose des résultats. Télécharger reçoit un fichier depuis un service vers un appareil : cela ne signifie pas l’envoyer à tous les autres. Zapper peut signifier passer rapidement d’un contenu à un autre, sans forcément le lire. Ces actions ne prouvent pas la qualité d’une information. Les modèles se comprennent sans appareil connecté.',
 'Scène originale : Bih cherche une explication pour le club. Elle navigue entre des pages, lit les indices de source puis demande à l’enseignante si un document est approprié avant de le télécharger. Ayuk remarque que zapper trop vite lui ferait manquer le contexte. Aucun fichier réel ni compte n’est nécessaire à l’exercice.',
 'Décris d’abord ce qui passe, d’où et vers où. Choisis ensuite le verbe. Face à une demande inconnue ou à un fichier douteux, demande l’aide d’un adulte de confiance plutôt que d’exécuter une instruction au hasard.',[
 F('naviguer','passer entre des pages ou ressources en ligne','Bih suit un lien vers une autre page.','Naviguer signifie obligatoirement imprimer chaque page.','Passer entre pages n’exige pas cette impression.'),
 F('chercher','formuler une demande pour trouver une information','Le groupe utilise les mots de sa question.','Chercher garantit que le premier résultat est vrai.','Un résultat doit encore être examiné.'),
 F('télécharger','recevoir un fichier depuis un service vers un appareil','Le modèle décrit un fichier reçu sur l’appareil.','Télécharger signifie forcément publier le fichier pour tous.','Le sens du transfert n’est pas cette publication.'),
 F('zapper','passer rapidement d’un contenu à un autre','Ayuk change de page sans finir le passage.','Zapper prouve une lecture approfondie de chaque texte.','La rapidité peut au contraire faire manquer le contexte.')],
 [('Un fichier passe du service vers l’appareil du modèle. Quelle action est décrite ?','télécharger',['publier pour tout le monde','imprimer sur papier','rester hors ligne sans transfert'],['La réception n’est pas la publication publique.','Aucun papier n’est produit.','Le modèle décrit bien un transfert.'],'Vérifie la direction du fichier.'),('Bih suit des liens entre des pages. Elle est en train de quoi ?','naviguer',['scanner une feuille','imprimer un message','effacer tout le réseau'],['Le texte ne décrit pas de numérisation.','Aucune impression n’est indiquée.','Le déplacement entre pages n’efface pas le réseau.'],'Le passage entre pages définit l’action.'),('Ayuk passe très vite d’un contenu à l’autre sans finir. Quel verbe convient ici ?','zapper',['tout vérifier en profondeur','archiver chaque document','rédiger une lettre complète'],['Le modèle précise qu’il ne termine pas la lecture.','La conservation n’est pas annoncée.','Il change de contenu, sans écrire cette lettre.'],'Le contexte décide du sens.'),('Le premier résultat s’affiche. Quelle conclusion est justifiée ?','Un résultat a été proposé et doit être examiné.',['Toute son information est garantie.','L’auteur de la page est forcément Bih.','Toutes les autres sources sont fausses.'],['L’ordre d’affichage n’est pas une garantie.','L’auteur n’est pas donné.','Aucune telle comparaison n’est établie.'],'Chercher et vérifier sont distincts.')],[71,72])

imperfect=B.mcq('fr2-74-conjuguer',2,'Conjugue « {v} » à l’imparfait avec « {fr2Pronoun(p)} ».','{fr2With(p,fr2Imparfait(v,p))}',
 [('{fr2With(p,fr2Present(v,p))}','present'),('{fr2With(p,fr2FuturSimple(v,p))}','futur'),('{fr2With(p,v)}','inf')],['Le récit demande une forme à l’imparfait.','Repère la personne et la base : {answer}.'],vars={'v':{'pick':['parler','envoyer','lire','écrire','manger','être']},'p':{'int':[0,7]}},misc=[('present','Cette forme est au présent, pas à l’imparfait demandé.'),('futur','Cette forme situe l’action au futur simple.'),('inf','L’infinitif ne porte pas la personne et le temps demandés.')],sources=SRC)
unit(74,'L’imparfait : habitudes et descriptions','former l’imparfait étudié et l’utiliser pour présenter une habitude ou un cadre passé',
 'les sujets et les actions de communication','la description et le court paragraphe',
 'L’imparfait peut présenter une habitude ou un état dans un cadre passé. On le forme généralement à partir de nous au présent, sans -ons, avec -ais, -ais, -ait, -ions, -iez et -aient. Être utilise la base ét-. Certains verbes demandent un ajustement orthographique : je mangeais mais nous mangions. Une activité passée n’est pas automatiquement un imparfait ; le contexte et le rôle dans le récit comptent. Ici, la consigne demande explicitement ce temps.',
 'Modèle original : Autrefois, Bih {fr2Imparfait("écrire",3)} les messages du club dans un cahier. Ayuk {fr2Imparfait("lire",2)} les annonces à voix haute. La salle {fr2Imparfait("être",3)} calme. Compare {fr2With(0,fr2Imparfait("envoyer",0))} et {fr2With(4,fr2Imparfait("envoyer",4))} : chaque sujet garde sa marque personnelle.',
 'Repère le sujet et l’intention passée. Retrouve le radical, ajoute la terminaison puis vérifie l’orthographe. Explique s’il s’agit d’une habitude ou d’un cadre, sans confondre le temps avec une mesure de durée.',[
 F('habitude passée','une action répétée dans un cadre passé','Chaque soir, Bih écrivait un message.','L’imparfait décrit obligatoirement une habitude actuelle.','Le cadre est ici passé.'),
 F('cadre descriptif','une présentation des circonstances du récit','La salle était calme décrit le cadre.','Chaque description à l’imparfait est une prédiction future.','Le modèle situe un état passé.'),
 F('radical','la base à laquelle on ajoute la terminaison','Être utilise ét- dans le modèle.','Tous les verbes gardent forcément leur infinitif entier à l’imparfait.','La formation doit retrouver la base adaptée.'),
 F('terminaison personnelle','la marque correspondant au sujet de l’imparfait','Nous écrivions emploie la personne de nous.','Nous au même temps impose toujours écriviez.','La terminaison de vous n’est pas celle de nous.')],imperfect,[72,73],example=L.worked({},'Écris à l’imparfait : nous / écrire un message.',['Au présent, nous donne {fr2Present("écrire",4)}.','On garde la base écriv- et la terminaison -ions.'],'{cap(fr2With(4,fr2Imparfait("écrire",4)))} un message.'))

def sounds(n,title,goal,back,onward,note,model,facts,bank,prereq):
    symbol_svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 150" role="img" aria-label="Modèles écrits de symboles phonétiques, sans son" font-family="Arial, sans-serif" fill="#183428"><rect width="320" height="150" fill="#fffdf5"/><text x="14" y="25" font-size="14">Symboles de préparation écrite</text><text x="22" y="76" font-size="30">[œ̃]</text><text x="127" y="76" font-size="30">[ɛ̃]</text><text x="242" y="76" font-size="30">[n]</text><text x="23" y="104" font-size="15">un</text><text x="127" y="104" font-size="15">vin</text><text x="238" y="104" font-size="15">nature</text><text x="14" y="135" font-size="12">Voyelles nasales et consonne nasale.</text></svg>'
    unit(n,title,goal,back,onward,note,model,
      'Repère le mot écrit et la graphie étudiée. Lis les symboles comme des indications, puis compare avec un modèle oral du professeur si possible. L’écran ne joue aucun enregistrement et ne mesure ni ton audition ni ta prononciation.',facts,choose(n,bank,key='graphies'),prereq,figure=json.dumps(symbol_svg,ensure_ascii=False))

sounds(75,'Préparer [œ̃] : un, brun, parfum','reconnaître les graphies étudiées de [œ̃] dans des mots écrits sans prétendre entendre un son',
 'les mots et leurs graphies','la comparaison de [ɛ̃] et [n] et une pratique orale guidée',
 'Dans le modèle phonétique de référence étudié, un, brun, commun et parfum contiennent la voyelle nasale [œ̃]. Les lettres un et um peuvent donc correspondre à ce modèle. Le signe au-dessus de la voyelle indique une nasalité ; il ne demande pas de prononcer séparément toutes les lettres finales. La prononciation varie dans la francophonie : [œ̃] et [ɛ̃] se rapprochent ou se confondent dans certains usages. Les exercices testent les graphies et le modèle annoncé, pas la valeur d’un accent ni une écoute réelle.',
 'Modèles écrits : un et brun présentent un ; parfum présente um ; commun finit par un. Ces mots ne signifient pas la même chose, même si une partie de leur prononciation correspond au modèle. Dans la suite pain, le modèle scolaire distingue [ɛ̃] de [œ̃], sans nier les usages où les timbres se rapprochent.',[
 F('voyelle nasale','une voyelle avec résonance par la cavité nasale','[œ̃] est une voyelle nasale dans le modèle.','Le signe nasal veut dire qu’aucune voyelle n’existe.','Il caractérise la voyelle, il ne la supprime pas.'),
 F('graphie un','une suite de lettres illustrée à la fin de brun','Brun finit par un.','Brun contient la graphie um à la fin.','Il faut observer les lettres réellement écrites.'),
 F('graphie um','une suite de lettres illustrée à la fin de parfum','Parfum finit par um.','Parfum doit être réécrit parfun pour cet exercice.','Le mot conserve sa graphie attestée.'),
 F('variation de prononciation','des réalisations différentes selon les usages','Certains usages rapprochent [œ̃] et [ɛ̃].','Tout rapprochement des timbres prouve un défaut moral.','La variation ne justifie aucun jugement sur la personne.')],
 [('Quel groupe est écrit à la fin de parfum ?','um',['un','ain','on'],['Le mot finit par m, non n.','Cette graphie appartient à d’autres mots comme pain.','Cette finale n’est pas présente.'],'Observe le mot écrit.'),('Quel groupe termine brun ?','un',['um','ein','an'],['Brun finit par n, pas m.','Le mot ne comporte pas ei.','La voyelle écrite est u.'],'Le modèle présente la graphie un.'),('Quel mot illustre um dans le modèle ?','parfum',['brun','un','commun'],['Brun présente un.','Le mot un ne comporte pas m.','La finale de commun est un.'],'La comparaison porte sur la graphie.'),('Quelle affirmation respecte la portée de l’activité ?','Elle prépare des graphies et un modèle phonétique écrit.',['Elle mesure la voix réelle de chaque élève.','Elle fournit un enregistrement de tous les accents.','Elle prouve que tous les usages ont les mêmes timbres.'],['Aucune voix n’est analysée.','Aucun son n’est fourni.','La variation est expliquée.'],'La pratique orale reste distincte.')],[74])

unit(76,'Personne, rien, aucun et chacun','employer une négation et accorder le verbe sans confondre absence et répartition',
 'les pronoms indéfinis et l’accord du sujet','la ponctuation et les messages précis',
 'Personne peut être un nom dans une personne ; dans personne ne parle, c’est un pronom négatif. Rien peut exprimer l’absence d’une chose : je ne vois rien. Dans les modèles négatifs étudiés, personne et rien s’emploient avec ne sans ajouter pas. Aucun reprend un élément dans une valeur nulle ; chacun considère les membres séparément et n’a pas cette valeur négative. Ces pronoms sujets sont singuliers dans les exemples. Le contexte décide de l’emploi : une même forme n’a pas toujours la même fonction.',
 'Modèles originaux : Personne ne {fr2Present("parler",2)} dans la scène. Je ne {fr2Present("voir",0)} rien sur la fiche. Aucun ne {fr2Present("lire",2)} le message dans cet exemple négatif. Chacun {fr2Present("lire",2)} sa question dans un autre exemple. Ces situations fictives ne décrivent pas un bilan de la classe.',
 'Demande si la phrase exprime une absence ou une action répartie entre les membres. Vérifie ensuite ne, la place du pronom et le sujet. Ne transforme pas chacun en personne uniquement parce que le groupe contient différents membres.',[
 F('personne pronom négatif','le pronom exprimant ici l’absence de personne','Personne ne parle est le modèle négatif.','Personne est toujours un nom féminin précédé de une.','L’emploi pronominal négatif diffère du nom une personne.'),
 F('rien pronom négatif','le pronom exprimant ici l’absence de chose','Je ne vois rien ne nomme aucun objet vu.','Rien signifie nécessairement plusieurs personnes identifiées.','Il porte ici sur une absence de chose.'),
 F('aucun pronom','une reprise à valeur nulle dans le modèle','Aucun ne lit le message est au singulier.','Aucun impose automatiquement lisent.','Le pronom sujet est singulier ici.'),
 F('chacun distributif','une reprise considérant chaque membre séparément','Chacun lit présente une action pour chaque membre.','Chacun signifie forcément personne ne lit.','La répartition ne signifie pas absence.')],
 choose(76,[('Choisis le modèle scolaire négatif demandé avec personne sujet.','Personne ne parle.',['Personne ne parle pas.','Personne ne parlent.','Chaque personne est obligatoirement absente parce que son nom est personne.'],['Dans ce modèle négatif simple, personne et ne suffisent sans pas.','Le sujet pronominal est singulier.','Le nom une personne ne signifie pas absence.'],'Distingue pronom, négation et accord.'),('Tu ne vois aucun objet sur la fiche. Quelle phrase conserve ce sens ?','Je ne vois rien.',['Je ne vois personne.','Plusieurs objets sont visibles.','Chacun voit nécessairement tout.'],['Personne porte sur les personnes, pas les choses demandées.','Cela inverse l’absence donnée.','Le contexte ne justifie pas cette affirmation.'],'Rien convient aux choses dans ce modèle.'),('Quel emploi de personne est nominal ?','Une personne lit.',['Personne ne lit.','Je ne vois personne.','Personne ne parle.'],['Dans personne ne lit, le pronom négatif est le sujet de lit.','Dans je ne vois personne, le pronom négatif est complément de vois.','Dans personne ne parle, le pronom négatif est sujet de parle, sans déterminant une.'],'Le déterminant une accompagne le nom.'),('Quelle phrase répartit une action sans exprimer une absence ?','Chacun lit sa question.',['Aucun ne lit.','Personne ne lit.','Je ne lis rien.'],['Aucun exprime ici la valeur nulle.','Personne exprime l’absence.','Rien exprime une absence de chose lue.'],'Chacun a une valeur distributive.')]),[72,74,75])

vocabulary(78,'Nommer les outils et messages des TIC','distinguer appareil logiciel recherche et message dans des situations écrites',
 'les actions de navigation et de téléchargement','le présent des verbes et le paragraphe de démarche',
 'Les TIC sont les technologies de l’information et de la communication. Un appareil comme un ordinateur ou une tablette permet d’utiliser des logiciels. Un navigateur affiche des pages du Web ; un moteur de recherche aide à trouver des ressources. Un courriel est un message électronique ; une pièce jointe accompagne ce message. Ces termes désignent des rôles différents. Un mot de passe protège un accès : l’exercice ne te demande jamais d’en fournir un. Les situations peuvent être comprises sur papier, sans compte ni appareil.',
 'Scène originale : Le club imaginaire prépare un courriel avec une fiche jointe. Bih distingue le navigateur qui affiche la page du moteur qui propose des résultats. Ayuk vérifie le destinataire avant de préparer l’envoi. Le texte ne donne ni adresse personnelle ni mot de passe.',
 'Demande si le mot nomme un outil, une fonction ou un message. Ne confonds pas la page affichée avec tout Internet. Si une demande exige un code secret ou une donnée privée, cherche l’aide d’un adulte de confiance.',[
 F('navigateur','un logiciel affichant des pages du Web','Le modèle ouvre une page dans un navigateur.','Navigateur est forcément le nom de chaque destinataire.','Il s’agit du logiciel, pas d’une personne.'),
 F('moteur de recherche','un service proposant des résultats pour une requête','Le club cherche des ressources avec des mots-clés.','Le moteur garantit que tous les résultats sont exacts.','Il propose des ressources qui restent à vérifier.'),
 F('courriel','un message électronique','Bih prépare un message destiné au club.','Un courriel est toujours une feuille déjà imprimée.','Le message est électronique ; une impression serait une autre action.'),
 F('pièce jointe','un fichier accompagnant un message','Une fiche est ajoutée au courriel du modèle.','La pièce jointe est forcément le mot de passe du compte.','C’est un fichier accompagnant le message, pas le secret d’accès.')],
 [('Quel outil affiche les pages du Web ?','un navigateur',['une pièce jointe','un destinataire','un mot de passe'],['Ce fichier n’est pas le logiciel d’affichage.','Le destinataire reçoit le message.','Le secret protège l’accès, sans afficher lui-même la page.'],'Distingue les rôles.'),('Le club formule une requête et reçoit des résultats. Quel service est utilisé ?','un moteur de recherche',['une impression papier','un clavier comme source de vérité','un mot de passe public'],['La situation décrit une recherche, pas une impression.','Le clavier sert à saisir, pas à garantir le contenu.','Un secret ne doit pas devenir public.'],'La requête oriente la recherche.'),('Un fichier accompagne le courriel. Comment le nommer ?','pièce jointe',['destinataire','mot de passe','navigateur'],['Le destinataire est la personne ou l’adresse visée.','Le fichier n’est pas le secret d’accès.','Le navigateur est un logiciel.'],'Le rôle dans le message décide.'),('Une demande inconnue exige ton mot de passe. Quelle réaction convient ?','Ne pas le communiquer et demander l’aide d’un adulte de confiance.',['Publier le secret pour toute la classe.','Le recopier dans l’exercice.','Supposer que toute demande est fiable.'],['Le partage expose l’accès.','L’exercice ne demande aucun code secret.','L’origine doit être examinée.'],'Garde le secret hors de cet exercice.')],[71,73,76])

punctuation=choose(77,[('Termine cette déclaration autonome avec un point : Bih prépare le message','Bih prépare le message.',['Bih prépare le message,','Bih prépare le message :','Bih, prépare, le message'],['La virgule ne clôt pas ici la déclaration autonome.','Aucune explication ou liste ne suit le deux-points.','Ces coupures séparent sans raison sujet, verbe et complément.'],'La consigne demande une déclaration terminée.'),('Choisis une liste simple correctement ponctuée.','Le club utilise des cahiers, des fiches et des livres.',['Le club utilise des cahiers des fiches des livres.','Le club utilise, des cahiers, des fiches et des livres.','Le club, utilise des cahiers des fiches et des livres.'],['Les éléments juxtaposés demandent une séparation claire.','Cette virgule sépare sans raison le verbe de son complément.','La virgule sépare ici sujet et verbe sans groupe inséré.'],'La virgule sépare les premiers éléments de la liste.'),('Introduis une liste après voici le matériel.','Voici le matériel : un cahier, une fiche et un livre.',['Voici le matériel, : un cahier une fiche un livre.','Voici le matériel : .','Voici : le matériel un cahier une fiche un livre'],['La combinaison et les éléments non séparés rendent la liste incorrecte.','Le deux-points n’introduit ici aucun contenu.','La coupure ne suit pas le groupe introducteur demandé.'],'Le deux-points annonce la liste.'),('Choisis la phrase qui garde sujet et verbe ensemble sans groupe inséré.','Ayuk lit le message.',['Ayuk, lit le message.','Ayuk : lit le message.','Ayuk. lit le message.'],['La virgule sépare sans raison le sujet et le verbe.','Le deux-points n’introduit ici ni explication ni liste.','Le point coupe la phrase et laisse un début incorrect.'],'La phrase simple garde sa construction.')])
unit(77,'Ponctuer : point, virgule et deux-points','ponctuer une déclaration et une liste puis expliquer les séparations choisies',
 'les sujets et les messages','la construction d’un paragraphe clair',
 'Le point termine une phrase déclarative autonome. Une virgule peut séparer des éléments d’une liste ; elle ne remplace pas automatiquement tous les points. Dans une phrase simple sans groupe inséré, on ne sépare pas le sujet et son verbe par une virgule. Les deux-points peuvent annoncer une liste ou une explication. Le signe doit correspondre au lien de sens et à la construction. Plusieurs présentations peuvent être possibles : les exercices précisent celle qui est demandée.',
 'Modèle original : Bih prépare une fiche. Voici son matériel : un cahier, un crayon et un livre. Ayuk lit le message. Les points terminent les déclarations ; les deux-points annoncent le matériel ; la virgule sépare les premiers éléments de la liste. Aucun signe n’est placé au hasard entre Ayuk et lit.',
 'Délimite d’abord les phrases et les groupes qui doivent rester ensemble. Choisis ensuite le signe et vérifie la majuscule après un point final. Lis le résultat pour contrôler le sens, pas seulement les pauses de respiration.',[
 F('point final','le signe terminant ici une déclaration autonome','Bih prépare une fiche. constitue une déclaration terminée.','Une virgule remplace toujours le point final dans tous les textes.','Les signes n’ont pas automatiquement le même rôle.'),
 F('virgule de liste','une séparation entre éléments juxtaposés','Un cahier, un crayon et un livre forme une liste.','Une liste impose une virgule après chaque lettre.','On sépare les éléments, pas chaque caractère.'),
 F('deux-points','un signe annonçant ici une liste','Voici le matériel : introduit les objets.','Les deux-points interdisent tout contenu après eux.','Ils annoncent précisément ce qui suit.'),
 F('groupe sujet-verbe','une construction qu’on ne coupe pas sans raison dans le modèle simple','Ayuk lit ne demande pas de virgule entre ses mots.','Ayuk, lit est toujours obligatoire sans groupe inséré.','La virgule ne doit pas séparer sans raison le sujet du verbe.')],punctuation,[76],paper={'prompt':'Rédige un bref message fictif qui annonce la préparation d’une fiche, énumère le matériel puis indique qui lit le résultat. Emploie un point final, une virgule de liste et des deux-points à bon escient.','model':['Bih prépare une fiche pour le club. Voici son matériel : un cahier, un crayon et un livre. Ayuk lit le message avant de le transmettre.'],'checklist':['Mes déclarations se terminent clairement.','La virgule sépare des éléments sans couper sujet et verbe.','Les deux-points annoncent bien la liste ; je vérifie les majuscules.'],'vars':{},'checks':[]})

sounds(79,'Préparer [ɛ̃] dans vin et pain, et [n] dans nature','distinguer voyelle nasale et consonne nasale dans les modèles écrits étudiés',
 'les graphies de [œ̃] et les mots des TIC','une lecture orale guidée et le paragraphe',
 'Dans le modèle étudié, vin et matin présentent la graphie in pour [ɛ̃] ; pain et main présentent ain pour cette même voyelle nasale. On ne prononce pas normalement un [n] séparé à la fin de ces mots isolés. Nature, navire et neige commencent par la consonne [n]. Cette consonne est elle aussi nasale, mais elle n’est pas une voyelle. Les graphies in ou ain ne suffisent pas à décider de tous les mots dans tous les contextes : on travaille ici sur les modèles annoncés.',
 'Modèles écrits : vin → in ; pain → ain ; main → ain ; matin → in dans la dernière syllabe. Nature et navire commencent par [n]. Dans le modèle isolé pain, le n participe à la graphie de la voyelle ; dans nature, il représente une consonne prononcée au début. Les indications ne sont pas un enregistrement.',[
 F('voyelle nasale [ɛ̃]','la voyelle de référence de vin et pain dans les mots isolés','Vin et pain partagent ce modèle vocalique.','Vin isolé impose ici un [n] final séparé après la voyelle.','Le n note ici la nasalité de la voyelle.'),
 F('graphie in','une suite de lettres illustrée dans vin','Vin contient i puis n.','Vin contient forcément la graphie ain.','Il faut lire les lettres présentes.'),
 F('graphie ain','une suite de lettres illustrée dans pain','Pain contient a, i puis n.','Pain doit être écrit pin dans tous les contextes.','La proximité de son n’efface pas l’orthographe du mot.'),
 F('consonne [n]','le son consonantique initial des modèles nature et navire','Nature commence par une consonne nasale.','Une consonne nasale est obligatoirement une voyelle.','La nasalité existe dans les deux catégories, qui restent distinctes.')],
 [('Quelle graphie est présente dans pain ?','ain',['in seulement','un','on'],['La lettre a est aussi présente dans le groupe.','La voyelle écrite n’est pas u.','La graphie ne comporte pas o.'],'Observe les lettres du mot.'),('Quel mot commence par la consonne [n] dans le modèle ?','nature',['vin','pain','matin'],['Le mot ne commence pas par n.','Il commence par p.','Il commence par m.'],'On demande le début consonantique.'),('Que représente le n à la fin de vin isolé dans le modèle ?','La nasalité de la voyelle, sans [n] final séparé.',['Une consonne initiale de vin.','Un ordre de prononcer une nouvelle syllabe ne.','Une preuve de la voix réelle de l’élève.'],['Le n écrit est final, pas initial.','Cette syllabe supplémentaire ne fait pas partie du modèle.','Aucune voix n’est analysée.'],'La graphie et les sons ne se lisent pas lettre par lettre.'),('Quelle affirmation distingue correctement les catégories ?','[ɛ̃] est une voyelle nasale ; [n] est une consonne nasale.',['Tout son nasal est une voyelle.','[n] ne peut jamais être nasal.','Le symbole écrit donne un diagnostic de l’audition.'],['Les consonnes nasales existent aussi.','[n] est précisément une consonne nasale.','L’exercice ne diagnostique pas l’audition.'],'La nasalité n’efface pas la distinction entre voyelle et consonne.')],[75,78])

present=B.mcq('fr2-80-conjuguer',2,'Conjugue « {v} » au présent avec « {fr2Pronoun(p)} ».','{fr2With(p,fr2Present(v,p))}',
 [('{fr2With(p,fr2Imparfait(v,p))}','passe'),('{fr2With(p,fr2FuturSimple(v,p))}','futur'),('{fr2With(p,v)}','inf')],['Repère le sujet et le présent demandé.','La forme est {answer}.'],vars={'v':{'pick':['parler','envoyer','recevoir','lire','écrire','faire']},'p':{'int':[0,7]}},misc=[('passe','Cette forme est à l’imparfait, pas au présent demandé.'),('futur','Cette forme est au futur simple.'),('inf','L’infinitif ne correspond pas à la forme personnelle demandée.')],sources=SRC)
unit(80,'Le présent : communiquer aujourd’hui','conjuguer des verbes de communication au présent en respectant leur modèle et le sujet',
 'les sujets indéfinis et la comparaison avec l’imparfait','l’écriture d’un court paragraphe cohérent',
 'Le présent peut décrire une action au moment envisagé ou une habitude actuelle. La personne et le verbe commandent la forme. Les verbes lire, écrire, recevoir, envoyer et faire ne suivent pas tous exactement parler. Pour écrire un message clair, repère le sujet avant de choisir la terminaison et la base. Avec je, une voyelle initiale peut demander une élision : j’écris. La présence d’aujourd’hui n’explique pas à elle seule chaque choix ; les exercices demandent explicitement le présent.',
 'Modèle original : Au club, Bih {fr2Present("écrire",3)} une fiche et Ayuk {fr2Present("lire",2)} la consigne. Ensemble, ils {fr2Present("faire",6)} une relecture. Compare {fr2With(0,fr2Present("recevoir",0))}, {fr2With(4,fr2Present("recevoir",4))} et {fr2With(5,fr2Present("envoyer",5))}. Le changement de personne peut modifier aussi le radical.',
 'Identifie le sujet, retrouve le modèle du verbe puis vérifie base, terminaison et élision. Réemploie ensuite une forme dans une phrase qui conserve le même référent. Ne déduis pas toute la conjugaison d’une seule finale.',[
 F('sujet grammatical','le groupe qui commande la personne du verbe','Bih commande la forme de écrit dans le modèle.','Le nom le plus proche après le verbe est toujours son sujet.','La fonction grammaticale doit être identifiée.'),
 F('forme personnelle','une conjugaison adaptée au sujet','Nous donne {fr2Present("écrire",4)}.','Nous écrire est la conjugaison personnelle attendue.','L’infinitif ne remplace pas la forme conjuguée.'),
 F('modèle irrégulier','une conjugaison qui ne suit pas entièrement parler','Vous donne {fr2Present("faire",5)} avec faire.','Faire doit donner faisez avec vous.','La forme particulière est faites.'),
 F('élision','la suppression écrite de la voyelle de je devant la forme adaptée','{cap(fr2With(0,fr2Present("écrire",0)))} emploie une apostrophe.','Je écris est l’écriture attendue du modèle.','Je s’élide devant la voyelle initiale de écris.')],present,[72,74,78,79])

paragraph=choose(81,[('Quelle phrase peut annoncer un paragraphe sur la préparation d’une fiche ?','Le club prépare une fiche de lecture.',['Les bananes sont mûres, sans lien avec la tâche.','Le résultat final est secret et le sujet absent.','Chaque mot doit changer de personnage.'],['La phrase change de thème sans lien annoncé.','Un sujet absent ne guide pas le lecteur.','Les référents doivent rester compréhensibles.'],'L’ouverture annonce l’idée principale.'),('Après le club prépare une fiche, quelle suite garde le thème ?','Bih note les idées utiles.',['La mer est profonde, sans lien expliqué.','Une identité privée doit être publiée.','Les mots ne doivent avoir aucun sens.'],['Le changement de sujet n’est pas relié.','La tâche ne demande pas de donnée privée.','La cohérence du sens est nécessaire.'],'Le détail développe la préparation.'),('Pourquoi ensuite convient-il entre préparation et relecture ?','Il indique une succession d’actions.',['Il signifie nécessairement parce que.','Il nomme un objet de la salle.','Il garantit que tout est vrai.'],['Cause et succession sont distinctes.','C’est un repère de progression.','Un connecteur ne vérifie pas les informations.'],'Le lien doit correspondre à l’ordre voulu.'),('Quelle relecture aide à suivre les personnages ?','Vérifier à qui renvoie chaque pronom.',['Changer les noms sans prévenir à chaque phrase.','Supprimer tous les liens de sens.','Remplacer tous les points par des noms.'],['Cela rend les référents confus.','Les liens sont nécessaires.','Les noms ne remplacent pas la ponctuation.'],'Le lecteur doit savoir qui agit.')])
unit(81,'Construire un court paragraphe','rédiger des phrases simples autour d’une même idée avec une progression et des reprises claires',
 'les messages, la ponctuation et le présent','les rédactions plus longues de la classe suivante',
 'Un paragraphe réunit des phrases autour d’une idée principale. Une ouverture peut annoncer cette idée, puis des détails la développent. Des mots comme d’abord et ensuite aident à suivre une démarche ; ils ne remplacent pas les actions elles-mêmes. Les pronoms doivent renvoyer clairement à des personnages ou objets. Relis les temps, les accords et les points. Un paragraphe court n’exige ni données privées ni phrases compliquées : la cohérence et la précision comptent.',
 'Modèle original : Le club de lecture imaginaire prépare une fiche. D’abord, Bih note les idées utiles. Ayuk lit les phrases et pose une question sur la source. Ensuite, le groupe vérifie le message avec l’enseignante. Les élèves gardent une version claire pour leur prochaine séance. Chaque phrase développe la même préparation sans annoncer une note finale inventée.',
 'Écris l’idée principale avant de choisir les détails. Ordonne les actions puis rédige des phrases simples complètes. Relis en demandant qui agit et à quoi renvoie chaque pronom. Vérifie enfin ponctuation et conjugaison.',[
 F('idée principale','le sujet commun développé par les phrases','La préparation d’une fiche relie le modèle.','Chaque phrase doit traiter un sujet sans rapport avec les autres.','Le paragraphe demande une unité de sens.'),
 F('détail pertinent','une information qui développe cette idée','La vérification de la source soutient la préparation.','Un détail est pertinent seulement parce qu’il révèle une adresse privée.','La pertinence dépend du sujet, pas d’une confidence.'),
 F('progression','l’ordre dans lequel les idées ou actions avancent','Ensuite relie des étapes successives.','Un connecteur de succession signifie toujours une cause.','Le lien doit correspondre à la relation voulue.'),
 F('reprise claire','un mot renvoyant à un référent identifiable','Le groupe reprend ici le club déjà annoncé.','Un pronom peut changer de référent sans aucun indice à chaque emploi.','Le lecteur doit pouvoir identifier le référent.')],paragraph,[70,71,77,80],paper={'prompt':'Rédige un court paragraphe au présent sur un club fictif qui prépare puis vérifie une fiche. Annonce le sujet, développe des étapes liées et garde les personnages identifiables.','model':['Le club imaginaire prépare une fiche de lecture. D’abord, Bih note les idées utiles. Ayuk lit les phrases et demande quelle source les soutient. Ensuite, le groupe vérifie le message avec l’enseignante. Les élèves gardent une version claire pour la séance suivante.'],'checklist':['Toutes mes phrases développent la même idée principale.','L’ordre et les reprises permettent de suivre qui agit.','Je vérifie phrases complètes, présent, accords, points et majuscules.'],'vars':{},'checks':[]})

